function paymentLinkModal(){
 const l=state.paymentLink;if(!l)return modalWrap('apm-payment-link-modal','Link de pagamento','<div class="apm-modal-body"></div>',true);
 const delivery=[];if(l.sent_whatsapp)delivery.push('WhatsApp');if(l.sent_email)delivery.push('e-mail');
 const failures=[];if(l.whatsapp_error)failures.push(`WhatsApp: ${esc(l.whatsapp_error)}`);if(l.email_error)failures.push(`E-mail: ${esc(l.email_error)}`);
 let deliveryNote;
 if(delivery.length&&!failures.length){deliveryNote=`Enviado automaticamente por ${delivery.join(' e ')} para ${esc(l.client_name||'o cliente')}.`}
 else if(delivery.length&&failures.length){deliveryNote=`Enviado por ${delivery.join(' e ')}, mas falhou em: ${failures.join(' · ')}. Copie o link abaixo e envie manualmente por esse outro canal.`}
 else if(failures.length){deliveryNote=`Não foi possível enviar automaticamente — ${failures.join(' · ')}. Copie o link abaixo e envie manualmente.`}
 else {deliveryNote='Não foi possível enviar automaticamente (sem WhatsApp configurado ou e-mail cadastrado) — copie o link abaixo e envie manualmente.'}
 return modalWrap('apm-payment-link-modal','Link de pagamento gerado',`<div class="apm-modal-body"><div class="apm-info-strip">${deliveryNote}</div><div class="apm-field full"><label>Link</label><div class="apm-copy-field"><input class="apm-input" value="${esc(l.checkout_url)}" readonly><button type="button" class="apm-btn apm-btn-secondary apm-btn-sm" data-copy="${esc(l.checkout_url)}">Copiar</button></div></div></div><div class="apm-modal-footer"><button type="button" class="apm-btn apm-btn-primary" data-close="apm-payment-link-modal">Concluir</button></div>`,true)
}
