function open(id){document.getElementById(id)?.classList.add('open')}function close(id){document.getElementById(id)?.classList.remove('open')}
// Campo de data com digitação livre (dd/mm/aaaa), reaproveitável em qualquer formulário:
// evita depender só do calendário nativo do navegador, importante para datas antigas
// (ex.: nascimento) onde clicar mês a mês no calendário é inviável.
function apmDateMaskDigits(v){return String(v||'').replace(/\D/g,'').slice(0,8)}
function apmDateMaskFormat(digits){let out=digits.slice(0,2);if(digits.length>2)out+='/'+digits.slice(2,4);if(digits.length>4)out+='/'+digits.slice(4,8);return out}
function apmDateMaskToIso(digits){
 if(digits.length!==8)return'';
 const d=Number(digits.slice(0,2)),m=Number(digits.slice(2,4)),y=Number(digits.slice(4,8));
 if(!d||!m||!y||d>31||m>12||y<1900||y>2100)return'';
 const dt=new Date(y,m-1,d);
 if(dt.getFullYear()!==y||dt.getMonth()!==m-1||dt.getDate()!==d)return''; // datas inexistentes, ex.: 31/02
 return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`
}
function bindDateMaskInputs(container){
 (container||document).querySelectorAll('[data-date-mask]').forEach(el=>{
  if(el.dataset.dateMaskBound==='1')return;el.dataset.dateMaskBound='1';
  const hidden=el.parentElement?.querySelector(`input[type="hidden"][name="${el.dataset.dateMask}"]`);
  if(!hidden)return;
  el.addEventListener('input',()=>{const digits=apmDateMaskDigits(el.value);el.value=apmDateMaskFormat(digits);hidden.value=apmDateMaskToIso(digits)})
 })
}
function fill(form,data){Object.entries(data||{}).forEach(([k,v])=>{if(k==='service_ids'){form.querySelectorAll('[name="service_ids"]').forEach(c=>c.checked=(v||[]).map(Number).includes(Number(c.value)));return}const el=form.elements[k];if(!el)return;if(el.type==='checkbox'){el.checked=!!Number(v)}else if(el.tagName==='SELECT'&&v!=null&&v!==''&&!Array.from(el.options).some(o=>o.value===String(v))){
 // Alguns campos de seleção (ex.: Origem do cliente) têm uma lista fixa de opções comuns,
 // mas o valor salvo pode ter vindo de um fluxo automático (agendamento online, cadastro
 // rápido...) que não está nessa lista. Sem isso, o navegador não acha a opção, o campo
 // fica em branco na tela, e salvar o formulário apaga silenciosamente o valor original.
 const opt=document.createElement('option');opt.value=String(v);opt.textContent=String(v);el.appendChild(opt);el.value=String(v)
}else{el.value=v??''}if(el.type==='hidden'){const masked=form.querySelector(`[data-date-mask="${k}"]`);if(masked)masked.value=v?formatDate(v):''}})}
function formObject(form){const fd=new FormData(form),o={};for(const [k,v] of fd.entries()){if(k==='service_ids'){if(!o[k])o[k]=[];o[k].push(Number(v))}else o[k]=v}form.querySelectorAll('input[type="checkbox"]').forEach(c=>{if(c.name!=='service_ids')o[c.name]=c.checked?1:0});return o}
